SELECT     TRUNC(SYSDATE)                                        AS report_date,      im.DEPT                                               AS dept_no,     d.DEPT_NAME                                           AS dept_name,     im.CLASS                                              AS class_no,     c.CLASS_NAME                                          AS class_name,     im.SUBCLASS                                           AS subclass_no,     sc.SUB_NAME                                           AS subclass_name,      im.ITEM                                               AS item_id,     im.ITEM_DESC                                          AS item_description,     im.STANDARD_UOM                                       AS uom,     im.STATUS                                             AS item_status,      ril.LOCATION                                          AS location_id,     il.LOC_TYPE                                           AS loc_type,     CASE il.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                   AS loc_type_desc,     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS location_name,     il.STATUS                                             AS item_loc_status,      ril.REPL_METHOD                                       AS repl_method,     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'DI' THEN 'Dynamic - Issues'         WHEN 'S'  THEN 'Dynamic - Seasonal'         WHEN 'TI' THEN 'Time Supply - Issues'         WHEN 'E'  THEN 'Time Supply - Seasonal'         ELSE ril.REPL_METHOD     END                                                   AS repl_method_desc,     ril.STOCK_CAT                                         AS stock_category,     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'         ELSE ril.STOCK_CAT     END                                                   AS stock_category_desc,     ril.REPL_ORDER_CTRL                                   AS order_control,     ril.PRIMARY_REPL_SUPPLIER                             AS supplier_id,     sp.SUP_NAME                                           AS supplier_name,     ril.SOURCE_WH                                         AS source_warehouse,     ril.MIN_STOCK                                         AS working_min_stock,     ril.MAX_STOCK                                         AS working_max_stock,     mra.PRES_STOCK                                        AS working_pres_stock,     ril.DEMO_STOCK                                        AS working_demo_stock,     ril.REVIEW_CYCLE                                      AS review_cycle,     ril.WH_LEAD_TIME                                      AS wh_lead_time,     ril.NON_SCALING_IND                                   AS scaling_exempt_ind,     ril.MAX_SCALE_VALUE                                   AS max_scale_amount,     ril.LAST_UPDATE_DATETIME                              AS last_repl_update,      mra.MIN_STOCK                                         AS master_min_stock,     mra.MAX_STOCK                                         AS master_max_stock,     mra.PRES_STOCK                                        AS master_pres_stock,     mra.REPL_METHOD                                       AS master_repl_method,     mra.REPL_ORDER_CTRL                                   AS master_order_control,     mra.PRIMARY_REPL_SUPPLIER                             AS master_supplier,     mra.STOCK_CAT                                         AS master_stock_category,      isc.LEAD_TIME                                         AS supp_lead_time,     isc.PICKUP_LEAD_TIME                                  AS pickup_lead_time,     isc.UNIT_COST                                         AS unit_cost,      ils.STOCK_ON_HAND                                     AS current_soh,      CASE         WHEN NVL(ril.MIN_STOCK, 0) > NVL(ril.MAX_STOCK, 0)         THEN 'YES - MIN(' || ril.MIN_STOCK || ') > MAX(' || ril.MAX_STOCK || ')'         ELSE 'OK'     END                                                   AS mm1_min_gt_max,      CASE         WHEN NVL(ril.MAX_STOCK, 0) = 0              AND ril.REPL_METHOD IN ('M','C','D','T','SO','DI','S','TI','E')         THEN 'YES - MAX_STOCK is zero on ' || ril.REPL_METHOD || ' method'         ELSE 'OK'     END                                                   AS mm2_max_stock_zero,      CASE         WHEN mra.ITEM IS NOT NULL              AND NVL(ril.MIN_STOCK, -9) != NVL(mra.MIN_STOCK, -9)         THEN 'YES - Working(' || ril.MIN_STOCK              || ') vs Master(' || mra.MIN_STOCK || ')'         WHEN mra.ITEM IS NULL THEN 'NO MASTER RECORD'         ELSE 'OK'     END                                                   AS mm3_min_vs_master,      CASE         WHEN mra.ITEM IS NOT NULL              AND NVL(ril.MAX_STOCK, -9) != NVL(mra.MAX_STOCK, -9)         THEN 'YES - Working(' || ril.MAX_STOCK              || ') vs Master(' || mra.MAX_STOCK || ')'         WHEN mra.ITEM IS NULL THEN 'NO MASTER RECORD'         ELSE 'OK'     END                                                   AS mm4_max_vs_master,      CASE         WHEN mra.ITEM IS NOT NULL              AND NVL(ril.REPL_METHOD, 'X') != NVL(mra.REPL_METHOD, 'X')         THEN 'YES - Working(' || ril.REPL_METHOD              || ') vs Master(' || mra.REPL_METHOD || ')'         WHEN mra.ITEM IS NULL THEN 'NO MASTER RECORD'         ELSE 'OK'     END                                                   AS mm5_method_vs_master,      CASE         WHEN mra.ITEM IS NOT NULL              AND NVL(ril.STOCK_CAT, 'X') != NVL(mra.STOCK_CAT, 'X')         THEN 'YES - Working(' || ril.STOCK_CAT              || ') vs Master(' || mra.STOCK_CAT || ')'         WHEN mra.ITEM IS NULL THEN 'NO MASTER RECORD'         ELSE 'OK'     END                                                   AS mm6_stock_cat_vs_master,      CASE         WHEN ril.PRIMARY_REPL_SUPPLIER IS NULL              AND ril.STOCK_CAT IN ('C','D','L','W')         THEN 'YES - Supplier required for ' || ril.STOCK_CAT         ELSE 'OK'     END                                                   AS mm7_supplier_missing,      CASE         WHEN ril.REPL_METHOD = 'SO'              AND ril.STOCK_CAT IN ('C','L','W')         THEN 'YES - Store Orders method incompatible with ' || ril.STOCK_CAT         ELSE 'OK'     END                                                   AS mm8_invalid_method_cat,      CASE         WHEN NVL(mra.PRES_STOCK, 0) > NVL(ril.MAX_STOCK, 0)              AND NVL(ril.MAX_STOCK, 0) > 0         THEN 'YES - PRES(' || mra.PRES_STOCK              || ') > MAX(' || ril.MAX_STOCK || ')'         ELSE 'OK'     END                                                   AS mm9_pres_gt_max,      (CASE WHEN NVL(ril.MIN_STOCK,0) > NVL(ril.MAX_STOCK,0)           THEN 1 ELSE 0 END      + CASE WHEN NVL(ril.MAX_STOCK,0) = 0                  AND ril.REPL_METHOD IN ('M','C','D','T','SO','DI','S','TI','E')              THEN 1 ELSE 0 END      + CASE WHEN mra.ITEM IS NOT NULL                  AND NVL(ril.MIN_STOCK,-9) != NVL(mra.MIN_STOCK,-9)              THEN 1 ELSE 0 END      + CASE WHEN mra.ITEM IS NOT NULL                  AND NVL(ril.MAX_STOCK,-9) != NVL(mra.MAX_STOCK,-9)              THEN 1 ELSE 0 END      + CASE WHEN mra.ITEM IS NOT NULL                  AND NVL(ril.REPL_METHOD,'X') != NVL(mra.REPL_METHOD,'X')              THEN 1 ELSE 0 END      + CASE WHEN mra.ITEM IS NOT NULL                  AND NVL(ril.STOCK_CAT,'X') != NVL(mra.STOCK_CAT,'X')              THEN 1 ELSE 0 END      + CASE WHEN ril.PRIMARY_REPL_SUPPLIER IS NULL                  AND ril.STOCK_CAT IN ('C','D','L','W')              THEN 1 ELSE 0 END      + CASE WHEN ril.REPL_METHOD = 'SO'                  AND ril.STOCK_CAT IN ('C','L','W')              THEN 1 ELSE 0 END      + CASE WHEN NVL(mra.PRES_STOCK,0) > NVL(ril.MAX_STOCK,0)                  AND NVL(ril.MAX_STOCK,0) > 0              THEN 1 ELSE 0 END     )                                                     AS total_mismatch_count,      CASE         WHEN NVL(ril.MIN_STOCK,0) > NVL(ril.MAX_STOCK,0)         THEN 'CRITICAL - Min exceeds Max, ROQ calculation broken'         WHEN ril.PRIMARY_REPL_SUPPLIER IS NULL              AND ril.STOCK_CAT IN ('C','D','L','W')         THEN 'HIGH - Supplier missing for required stock category'         WHEN ril.REPL_METHOD = 'SO'              AND ril.STOCK_CAT IN ('C','L','W')         THEN 'HIGH - Method/Category combination invalid'         WHEN NVL(ril.MAX_STOCK,0) = 0              AND ril.REPL_METHOD IN ('M','C','D','T','SO')         THEN 'HIGH - Max Stock zero causes zero ROQ'         WHEN mra.ITEM IS NOT NULL              AND (NVL(ril.MIN_STOCK,-9) != NVL(mra.MIN_STOCK,-9)                OR NVL(ril.MAX_STOCK,-9) != NVL(mra.MAX_STOCK,-9))         THEN 'MEDIUM - Working params diverged from Master baseline'         WHEN mra.ITEM IS NOT NULL              AND (NVL(ril.REPL_METHOD,'X') != NVL(mra.REPL_METHOD,'X')                OR NVL(ril.STOCK_CAT,'X')   != NVL(mra.STOCK_CAT,'X'))         THEN 'MEDIUM - Method or Category differs from Master'         WHEN NVL(mra.PRES_STOCK,0) > NVL(ril.MAX_STOCK,0)         THEN 'LOW - Presentation stock exceeds Max stock'         ELSE 'LOW - Review'     END                                                   AS mismatch_priority,      CASE         WHEN NVL(ril.MIN_STOCK,0) > NVL(ril.MAX_STOCK,0)         THEN 'Correct MIN_STOCK or MAX_STOCK via Replenishment Attribute Update; MIN must be < MAX'         WHEN ril.PRIMARY_REPL_SUPPLIER IS NULL              AND ril.STOCK_CAT IN ('C','D','L','W')         THEN 'Assign valid SUPPLIER on REPL_ITEM_LOC via rplatupd spreadsheet upload'         WHEN ril.REPL_METHOD = 'SO'              AND ril.STOCK_CAT IN ('C','L','W')         THEN 'Change REPL_METHOD to valid method for WH stock category (D, M, C, T, F)'         WHEN NVL(ril.MAX_STOCK,0) = 0         THEN 'Set MAX_STOCK > 0 to enable ROQ calculation for this method'         WHEN mra.ITEM IS NOT NULL              AND (NVL(ril.MIN_STOCK,-9) != NVL(mra.MIN_STOCK,-9)                OR NVL(ril.MAX_STOCK,-9) != NVL(mra.MAX_STOCK,-9))         THEN 'Use Update from Master Attributes=Y in Repl WP upload to reset from master baseline'         ELSE 'Review via Replenishment Attribute Update screen and correct mismatched fields'     END                                                   AS recommended_action  FROM     MFCS_RDS.RDS_WV_REPL_ITEM_LOC              ril      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC             il    ON  ril.ITEM                   = il.ITEM                                                      AND  ril.LOCATION               = il.LOC                                                      AND  ril.LOC_TYPE               = il.LOC_TYPE     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER          im    ON  ril.ITEM                   = im.ITEM                                                      AND  im.TRAN_LEVEL              = im.ITEM_LEVEL     JOIN  MFCS_RDS.RDS_WV_DEPS                 d     ON  im.DEPT                    = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                c     ON  im.DEPT                    = c.DEPT                                                      AND  im.CLASS                   = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc    ON  im.DEPT                    = sc.DEPT                                                      AND  im.CLASS                   = sc.CLASS                                                      AND  im.SUBCLASS                = sc.SUBCLASS      LEFT JOIN MFCS_RDS.RDS_WV_MASTER_REPL_ATTR mra   ON  ril.ITEM                   = mra.ITEM                                                      AND  ril.LOCATION               = mra.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_STORE            st    ON  ril.LOCATION               = st.STORE                                                      AND  il.LOC_TYPE                = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH              wh     ON  ril.LOCATION               = wh.WH                                                      AND  il.LOC_TYPE                = 'W'     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH    ils    ON  ril.ITEM                   = ils.ITEM                                                      AND  ril.LOCATION               = ils.LOC                                                      AND  ils.LOC_TYPE               = ril.LOC_TYPE     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  ril.ITEM                   = isc.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER  = isc.SUPPLIER                                                      AND  isc.PRIMARY_SUPP_IND       = 'Y'                                                      AND  isc.PRIMARY_COUNTRY_IND    = 'Y'     LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp    ON  ril.PRIMARY_REPL_SUPPLIER  = sp.SUPPLIER  WHERE     ril.REPL_METHOD  IS NOT NULL     AND il.STATUS    IN ('A','C')     AND im.STATUS     = 'A'     AND (         NVL(ril.MIN_STOCK, 0) > NVL(ril.MAX_STOCK, 0)         OR (NVL(ril.MAX_STOCK, 0) = 0             AND ril.REPL_METHOD IN ('M','C','D','T','SO','DI','S','TI','E'))         OR (mra.ITEM IS NOT NULL             AND (NVL(ril.MIN_STOCK,-9)  != NVL(mra.MIN_STOCK,-9)               OR NVL(ril.MAX_STOCK,-9)  != NVL(mra.MAX_STOCK,-9)))         OR (mra.ITEM IS NOT NULL             AND (NVL(ril.REPL_METHOD,'X') != NVL(mra.REPL_METHOD,'X')               OR NVL(ril.STOCK_CAT,'X')   != NVL(mra.STOCK_CAT,'X')))         OR (ril.PRIMARY_REPL_SUPPLIER IS NULL             AND ril.STOCK_CAT IN ('C','D','L','W'))         OR (ril.REPL_METHOD = 'SO'             AND ril.STOCK_CAT IN ('C','L','W'))         OR (NVL(mra.PRES_STOCK, 0) > NVL(ril.MAX_STOCK, 0)             AND NVL(ril.MAX_STOCK, 0) > 0)     )  ORDER BY     (CASE WHEN NVL(ril.MIN_STOCK,0) > NVL(ril.MAX_STOCK,0) THEN 1 ELSE 0 END      + CASE WHEN NVL(ril.MAX_STOCK,0)=0                  AND ril.REPL_METHOD IN ('M','C','D','T','SO','DI','S','TI','E')              THEN 1 ELSE 0 END      + CASE WHEN mra.ITEM IS NOT NULL                  AND NVL(ril.MIN_STOCK,-9) != NVL(mra.MIN_STOCK,-9)              THEN 1 ELSE 0 END      + CASE WHEN mra.ITEM IS NOT NULL                  AND NVL(ril.MAX_STOCK,-9) != NVL(mra.MAX_STOCK,-9)              THEN 1 ELSE 0 END      + CASE WHEN mra.ITEM IS NOT NULL                  AND NVL(ril.REPL_METHOD,'X') != NVL(mra.REPL_METHOD,'X')              THEN 1 ELSE 0 END      + CASE WHEN mra.ITEM IS NOT NULL                  AND NVL(ril.STOCK_CAT,'X') != NVL(mra.STOCK_CAT,'X')              THEN 1 ELSE 0 END      + CASE WHEN ril.PRIMARY_REPL_SUPPLIER IS NULL                  AND ril.STOCK_CAT IN ('C','D','L','W') THEN 1 ELSE 0 END      + CASE WHEN ril.REPL_METHOD='SO'                  AND ril.STOCK_CAT IN ('C','L','W') THEN 1 ELSE 0 END      + CASE WHEN NVL(mra.PRES_STOCK,0) > NVL(ril.MAX_STOCK,0)                  AND NVL(ril.MAX_STOCK,0) > 0 THEN 1 ELSE 0 END     ) DESC,     CASE         WHEN NVL(ril.MIN_STOCK,0) > NVL(ril.MAX_STOCK,0)         THEN 'CRITICAL - Min exceeds Max, ROQ calculation broken'         WHEN ril.PRIMARY_REPL_SUPPLIER IS NULL              AND ril.STOCK_CAT IN ('C','D','L','W')         THEN 'HIGH - Supplier missing for required stock category'         WHEN ril.REPL_METHOD='SO' AND ril.STOCK_CAT IN ('C','L','W')         THEN 'HIGH - Method/Category combination invalid'         WHEN NVL(ril.MAX_STOCK,0)=0              AND ril.REPL_METHOD IN ('M','C','D','T','SO')         THEN 'HIGH - Max Stock zero causes zero ROQ'         ELSE 'MEDIUM'     END,     d.DEPT_NAME,     im.ITEM_DESC,     CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END